#!/usr/bin/env node
/*
 * One registry, three readers: the app's TypeScript types, the Rust host's enum,
 * and docs/state-machines.md. Run with no argument to write them; run with
 * "--check" to fail when a committed file is out of date.
 *
 * The registry is src/shared/stateMachines.json. Generated files say so in their
 * header, so nobody edits them by hand.
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const REGISTRY = join(ROOT, "src", "shared", "stateMachines.json");
const LIFECYCLES = join(ROOT, "src", "shared", "lifecycles.json");
const TS_OUT = join(ROOT, "src", "shared", "stateMachines.generated.ts");
const RUST_OUT = join(ROOT, "src-tauri", "src", "state_machine.rs");
const DOCS_OUT = join(ROOT, "docs", "state-machines.md");

const HEADER = "Generated by scripts/generate-state-machines.mjs from src/shared/stateMachines.json. Do not edit.";

function loadRegistry() {
  const registry = JSON.parse(readFileSync(REGISTRY, "utf8"));
  validate(registry);
  return registry;
}

function fail(message) {
  throw new Error(`${relative(ROOT, REGISTRY)}: ${message}`);
}

function validate(registry) {
  if (!registry || !Array.isArray(registry.machines) || registry.machines.length === 0) fail("machines must be a non-empty array");
  const ids = new Set();
  for (const machine of registry.machines) {
    for (const field of ["id", "title", "description", "initial"]) {
      if (typeof machine[field] !== "string" || !machine[field].trim()) fail(`machine is missing ${field}`);
    }
    if (ids.has(machine.id)) fail(`machine ${machine.id} appears twice`);
    ids.add(machine.id);
    if (!Array.isArray(machine.states) || machine.states.length === 0) fail(`${machine.id}: states must be a non-empty array`);
    const states = new Set();
    for (const state of machine.states) {
      if (typeof state.id !== "string" || !/^[a-z][a-z0-9_]*$/.test(state.id)) fail(`${machine.id}: bad state id ${state.id}`);
      if (states.has(state.id)) fail(`${machine.id}: state ${state.id} appears twice`);
      states.add(state.id);
      if (typeof state.label !== "string" || !state.label.trim()) fail(`${machine.id}.${state.id}: missing label`);
      if (typeof state.description !== "string" || !state.description.trim()) fail(`${machine.id}.${state.id}: missing description`);
    }
    if (!states.has(machine.initial)) fail(`${machine.id}: initial state ${machine.initial} is not a state`);
    if (!Array.isArray(machine.transitions) || machine.transitions.length === 0) fail(`${machine.id}: transitions must be a non-empty array`);
    const edges = new Set();
    const pairs = new Set();
    const events = new Set();
    for (const transition of machine.transitions) {
      const { from, to, event } = transition;
      if (!states.has(from)) fail(`${machine.id}: transition from unknown state ${from}`);
      if (!states.has(to)) fail(`${machine.id}: transition to unknown state ${to}`);
      if (typeof event !== "string" || !/^[a-z][a-z0-9_]*$/.test(event)) fail(`${machine.id}: bad event ${event}`);
      if (edges.has(`${from}/${to}/${event}`)) fail(`${machine.id}: transition ${from} -> ${to} on ${event} appears twice`);
      edges.add(`${from}/${to}/${event}`);
      pairs.add(`${from}/${to}`);
      if (events.has(`${from}/${event}`)) fail(`${machine.id}: event ${event} is ambiguous from ${from}`);
      events.add(`${from}/${event}`);
      if (typeof transition.description !== "string" || !transition.description.trim()) fail(`${machine.id}: transition ${from} -> ${to} needs a description`);
    }
    for (const [from, to] of machine.rejects ?? []) {
      if (!states.has(from) || !states.has(to)) fail(`${machine.id}: rejected pair ${from} -> ${to} names an unknown state`);
      if (pairs.has(`${from}/${to}`)) fail(`${machine.id}: ${from} -> ${to} is both allowed and rejected`);
    }
    if (machine.rust !== undefined && !/^[A-Z][A-Za-z0-9]*$/.test(machine.rust)) fail(`${machine.id}: bad Rust enum name ${machine.rust}`);
  }
  const rustMachines = registry.machines.filter((machine) => machine.rust);
  if (rustMachines.length === 0) fail("at least one machine must be generated into Rust");
}

function keyedMachines(registry) {
  return Object.fromEntries(registry.machines.map((machine) => [machine.id, {
    id: machine.id,
    title: machine.title,
    description: machine.description,
    initial: machine.initial,
    states: machine.states,
    transitions: machine.transitions,
    rejects: machine.rejects ?? []
  }]));
}

function typescript(registry) {
  return `/* ${HEADER} */
/* eslint-disable */

export const STATE_MACHINES = ${JSON.stringify(keyedMachines(registry), null, 2)} as const;

export type MachineId = keyof typeof STATE_MACHINES;
export type MachineState<M extends MachineId> = (typeof STATE_MACHINES)[M]["states"][number]["id"];

/** The server states reported to the window and the Node sidecar. */
export type ServerState = MachineState<"server">;
/** One voice conversation. */
export type VoiceState = MachineState<"voice">;
/** The overall result of one file build. */
export type BuildStatus = MachineState<"build">;
/** One project's knowledge index. */
export type KnowledgeIndexState = MachineState<"knowledgeIndex">;
`;
}

function pascal(id) {
  return id.split(/[^A-Za-z0-9]+/).filter(Boolean).map((part) => part[0].toUpperCase() + part.slice(1)).join("");
}

function rust(registry) {
  const machines = registry.machines.filter((entry) => entry.rust);
  return `// ${HEADER}

use serde::{Deserialize, Serialize};

${machines.map((machine) => rustEnum(machine)).join("\n")}`;
}

function rustEnum(machine) {
  const name = machine.rust;
  // the initial state is the derived default (#[default]), not a hand-written impl
  const variants = machine.states.map((state) => `${state.id === machine.initial ? "    #[default]\n" : ""}    ${pascal(state.id)}, // ${state.id}`);
  const names = machine.states.map((state) => `            Self::${pascal(state.id)} => "${state.id}",`).join("\n");
  const parse = machine.states.map((state) => `            "${state.id}" => Ok(Self::${pascal(state.id)}),`).join("\n");
  const all = machine.states.map((state) => `Self::${pascal(state.id)}`).join(", ");
  const legal = machine.transitions
    .map((transition) => `            (Self::${pascal(transition.from)}, Self::${pascal(transition.to)})`)
    .join(" |\n");
  const events = machine.transitions
    .map((transition) => `            (Self::${pascal(transition.from)}, "${transition.event}") => Some(Self::${pascal(transition.to)}),`)
    .join("\n");
  const legalTests = machine.transitions
    .map((transition) => `        assert!(${name}::${pascal(transition.from)}.can_transition_to(${name}::${pascal(transition.to)}));`)
    .join("\n");
  const rejectTests = (machine.rejects ?? [])
    .map(([from, to]) => `        assert!(!${name}::${pascal(from)}.can_transition_to(${name}::${pascal(to)}));`)
    .join("\n");
  const testMod = `mod ${machine.id.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase()}_tests`;
  return `/// ${machine.description.replace(/\n/g, " ")}
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ${name} {
${variants.join("\n")}
}

impl ${name} {
    pub const ALL: [Self; ${machine.states.length}] = [${all}];

    pub fn as_str(self) -> &'static str {
        match self {
${names}
        }
    }

    /// Every transition the registry allows. A state may always stay where it is.
    pub fn can_transition_to(self, next: Self) -> bool {
        self == next || matches!(
            (self, next),
${legal}
        )
    }

    /// The next state for one named event, when the event applies to this state.
    pub fn next(self, event: &str) -> Option<Self> {
        match (self, event) {
${events}
            _ => None,
        }
    }
}

impl std::str::FromStr for ${name} {
    type Err = ();

    fn from_str(value: &str) -> Result<Self, Self::Err> {
        match value {
${parse}
            _ => Err(()),
        }
    }
}

#[cfg(test)]
${testMod} {
    use super::*;

    #[test]
    fn every_state_has_a_name_that_parses_back() {
        for state in ${name}::ALL {
            assert_eq!(state.as_str().parse::<${name}>(), Ok(state));
        }
    }

    #[test]
    fn the_registry_transitions_are_legal() {
${legalTests}
    }

    #[test]
    fn impossible_jumps_are_rejected() {
${rejectTests}
    }

    #[test]
    fn events_follow_the_registry() {
${machine.transitions.map((transition) => `        assert_eq!(${name}::${pascal(transition.from)}.next("${transition.event}"), Some(${name}::${pascal(transition.to)}));`).join("\n")}
    }
}
`;
}

function loadLifecycles() {
  const data = JSON.parse(readFileSync(LIFECYCLES, "utf8"));
  if (!data || !Array.isArray(data.lifecycles)) fail("lifecycles.json: lifecycles must be an array");
  const allowed = new Set(["migrated", "not-migrated", "not-a-machine"]);
  for (const entry of data.lifecycles) {
    for (const field of ["id", "title", "owner", "classification", "where", "reason"]) {
      if (typeof entry[field] !== "string" || !entry[field].trim()) fail(`lifecycles.json ${entry.id ?? "?"}: missing ${field}`);
    }
    if (!allowed.has(entry.classification)) fail(`lifecycles.json ${entry.id}: bad classification ${entry.classification}`);
    if (!Array.isArray(entry.scan)) fail(`lifecycles.json ${entry.id}: scan must be an array`);
  }
  return data;
}

function inventoryMarkdown() {
  const data = loadLifecycles();
  const groups = { migrated: [], "not-migrated": [], "not-a-machine": [] };
  for (const entry of data.lifecycles) groups[entry.classification].push(entry);
  const row = (entry) =>
    `| \`${entry.id}\` | ${entry.title} | ${entry.owner} | ${entry.userVisible ? "yes" : "no"} | ${entry.where} | ${entry.reason.replace(/\n/g, " ")} |`;
  const head = "| Id | Title | Owner | User-visible | Where | How it is handled |\n| --- | --- | --- | --- | --- | --- |";
  const section = (title, note, entries) =>
    `### ${title} (${entries.length})\n\n${note}\n\n${entries.length ? `${head}\n${entries.map(row).join("\n")}` : "_None._"}\n`;
  const total = data.lifecycles.length;
  return `
## Every lifecycle in the program

This is the complete inventory the \`scripts/lib/lifecycle-scan.mjs\` scan looks after. Every
named state/status/phase/stage/step type, and every status/phase/worker union, found in the
source must appear here (as a migrated machine or as an inventory entry), and
\`tests/state-machines.test.ts\` fails when one does not. ${total} lifecycles are listed:
${groups.migrated.length} migrated, ${groups["not-migrated"].length} a real machine not migrated yet,
${groups["not-a-machine"].length} not a state machine.

${section("Migrated", "In `src/shared/stateMachines.json`; the generated types, the Rust enum and the tables above are their source of truth.", groups.migrated)}
${section("A real machine, not migrated yet", "Has states and events but does not use the registry yet. Registered most user-visible first.", groups["not-migrated"])}
${section("Not a state machine", "A status label, a boolean, a linear progress value or a one-shot classification with no transitions to guard.", groups["not-a-machine"])}
`;
}

function markdown(registry) {
  const machines = registry.machines.map((machine) => {
    const states = machine.states.map((state) => `| \`${state.id}\` | ${state.label} | ${state.description} |`).join("\n");
    const transitions = machine.transitions
      .map((transition) => `| \`${transition.from}\` | \`${transition.event}\` | \`${transition.to}\` | ${transition.description} |`)
      .join("\n");
    const rejects = (machine.rejects ?? []).map(([from, to]) => `- \`${from}\` → \`${to}\``).join("\n");
    return `## ${machine.title} (\`${machine.id}\`)

${machine.description}

Initial state: \`${machine.initial}\`

| State | Name | Meaning |
| --- | --- | --- |
${states}

| From | Event | To | Meaning |
| --- | --- | --- | --- |
${transitions}

${rejects ? `Forbidden jumps (a shorter path is a bug):\n\n${rejects}` : "No forbidden jumps."}
`;
  }).join("\n");

  return `# State machines

<!-- ${HEADER} -->

The source of truth is \`src/shared/stateMachines.json\`. The same registry writes the
TypeScript types in \`src/shared/stateMachines.generated.ts\`, the Rust enum in
\`src-tauri/src/state_machine.rs\`, and this page. A state may always stay where it is;
every other move must be one of the transitions below.

Run \`node scripts/generate-state-machines.mjs\` after editing the registry, and
\`node scripts/generate-state-machines.mjs --check\` to verify that everything is in step.

${machines}
${inventoryMarkdown()}`;
}

function outputs(registry) {
  return [
    [TS_OUT, typescript(registry)],
    [RUST_OUT, rust(registry)],
    [DOCS_OUT, markdown(registry)]
  ];
}

function write(file, content) {
  mkdirSync(dirname(file), { recursive: true });
  const previous = (() => { try { return readFileSync(file, "utf8"); } catch { return null; } })();
  if (previous === content) return false;
  writeFileSync(file, content, "utf8");
  return true;
}

function main() {
  const check = process.argv.includes("--check");
  const registry = loadRegistry();
  const files = outputs(registry);
  if (check) {
    const stale = files.filter(([file, content]) => {
      // compare with line endings normalized: a Windows checkout holds CRLF
      try { return readFileSync(file, "utf8").replace(/\r\n/g, "\n") !== content; } catch { return true; }
    });
    if (stale.length) {
      for (const [file] of stale) console.error(`out of date: ${relative(ROOT, file)}`);
      console.error("run: node scripts/generate-state-machines.mjs");
      process.exit(1);
    }
    console.log(`state machines are up to date (${registry.machines.length} machines)`);
    return;
  }
  const changed = files.filter(([file, content]) => write(file, content)).map(([file]) => relative(ROOT, file));
  console.log(changed.length ? `wrote ${changed.join(", ")}` : "state machines are already up to date");
}

main();
